import React, { useEffect, useState, useRef } from "react";
import { useParams, useNavigate } from "react-router-dom";
import { GoogleMap, Marker, useJsApiLoader, DirectionsRenderer } from "@react-google-maps/api";
import io from "socket.io-client";

const API_BASE_URL = process.env.REACT_APP_API_URL || "http://localhost:5000";
const SOCKET_URL = "http://localhost:5000"; // Update if different
const GOOGLE_MAPS_API_KEY = process.env.REACT_APP_GOOGLE_MAPS_API_KEY || "";

const containerStyle = {
  width: "100%",
  height: "600px",
};

const defaultCenter = {
  lat: 6.9271, // Colombo default center
  lng: 79.8612,
};

interface Location {
  lat: number;
  lng: number;
}

export default function DeliveryTracking() {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const [driverLocation, setDriverLocation] = useState<Location | null>(null);
  const [destination, setDestination] = useState<Location | null>(null);
  const [directions, setDirections] = useState<google.maps.DirectionsResult | null>(null);
  const mapRef = useRef<google.maps.Map | null>(null);

  const { isLoaded } = useJsApiLoader({
    googleMapsApiKey: GOOGLE_MAPS_API_KEY,
  });

  useEffect(() => {
    if (!id) return;

    // ✅ Fetch the delivery details to get destination (customer address)
    const fetchDelivery = async () => {
      try {
        const res = await fetch(`${API_BASE_URL}/api/delivery/${id}`);
        const data = await res.json();
        if (data?.location) {
          setDestination({
            lat: data.location.lat,
            lng: data.location.lng,
          });
        }
      } catch (error) {
        console.error("❌ Failed to fetch delivery:", error);
      }
    };

    fetchDelivery();

    // ✅ Setup Socket.IO connection
    const socket = io(SOCKET_URL);

    socket.emit('trackDelivery', id);

    socket.on('driverLocationUpdate', (location: Location) => {
      console.log('📍 Received driver location update:', location);
      setDriverLocation(location);
    });

    return () => {
      socket.disconnect();
    };
  }, [id]);

  useEffect(() => {
    if (driverLocation && destination) {
      const directionsService = new google.maps.DirectionsService();
      directionsService.route(
        {
          origin: driverLocation,
          destination: destination,
          travelMode: google.maps.TravelMode.DRIVING,
        },
        (result, status) => {
          if (status === google.maps.DirectionsStatus.OK) {
            setDirections(result);
          } else {
            console.error("❌ Failed to fetch directions:", status);
          }
        }
      );
    }
  }, [driverLocation, destination]);

  if (!isLoaded) return <div>Loading Google Maps...</div>;

  return (
    <div style={{ padding: "20px" }}>
      <h2>Tracking Delivery</h2>

      <div style={{ marginBottom: "20px" }}>
        <button
          onClick={() => navigate("/")}
          style={{
            padding: "10px 20px",
            backgroundColor: "#6c757d",
            color: "#fff",
            border: "none",
            borderRadius: "6px",
            cursor: "pointer",
          }}
        >
          ← Back to Dashboard
        </button>
      </div>

      <GoogleMap
        mapContainerStyle={containerStyle}
        center={driverLocation || destination || defaultCenter}
        zoom={14}
        onLoad={(map) => {
          mapRef.current = map;
        }}
      >
        {driverLocation && (
          <Marker
            position={driverLocation}
            label="🚚 Driver"
          />
        )}

        {destination && (
          <Marker
            position={destination}
            label="📍 Destination"
          />
        )}

        {directions && <DirectionsRenderer directions={directions} />}
      </GoogleMap>
    </div>
  );
}
